export const FIRST_BUS_ROUTE = { routeId: 1, routeCode: '23', firstStationId: 134 };

export const seedNetworkData: TransitNetworkData = {
  stations: stations.map(([code, name, lat, lng, typeId], i) => ({
    stationId: i + 1,
    stationCode: code,
    stationName: name,
    latitude: lat,
    longitude: lng,
    address: null,
    transportTypeId: typeId,
    transportTypeName: TYPE_NAMES[typeId],
    status: 'ACTIVE',
  })),
  routes: routes.map(([code, name, typeId], i) => ({
    routeId: i + 1,
    routeCode: code,
    routeName: name,
    transportTypeId: typeId,
    transportTypeName: TYPE_NAMES[typeId],
    mode: typeId === 1 ? 'BUS' : typeId === 2 ? 'METRO' : typeId === 3 ? 'BICYCLE' : 'ELECTRIC_VEHICLE',
    status: 'ACTIVE',
  })),
  routeStops: routeStops.map(([routeId, stationId, stopOrder, distanceFromStart]) => ({
    routeId,
    stationId,
    stopOrder,
    distanceFromStart,
  })),
  fareRules: fareRules.map(([transportTypeId, fromStationId, toStationId, price]) => ({
    transportTypeId,
    fromStationId,
    toStationId,
    price,
  })),
  attractionAccess: attractionAccess.map(([attractionId, stationId, walkingDistance, walkingDuration]) => ({
    attractionId,
    stationId,
    walkingDistance,
    walkingDuration,
  })),
  departures: {
    // Tuyen buyt dau tien tai tram dau: 05:00 -> 21:00 moi 20 phut
    [`${FIRST_BUS_ROUTE.routeId}:${FIRST_BUS_ROUTE.firstStationId}`]: Array.from({ length: 49 }, (_, i) => {
      const m = 300 + i * 20;
      return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
    }),
  },
};
